<template>
  <div class="pga-root">
    <!-- Loading Overlay -->
    <v-overlay :value="loading" z-index="999">
      <div class="pga-loader">
        <div class="pga-loader__dots">
          <span></span><span></span><span></span>
        </div>
        <div class="pga-loader__text">Loading adjustment...</div>
      </div>
    </v-overlay>

    <!-- Hero Header -->
    <header class="pga-hero">
      <div class="pga-hero__pattern"></div>
      <div class="pga-hero__inner">
        <div class="pga-hero__breadcrumb">
          <span class="pga-hero__back" @click="goHome">
            <v-icon size="13" color="rgba(255,255,255,0.6)"
              >mdi-arrow-left</v-icon
            >
            Back
          </span>
          <v-icon size="12" color="#fdba74">mdi-chevron-right</v-icon>
          <v-icon size="14" color="#f97316">mdi-home</v-icon>
          <span>Ministry of Health</span>
          <v-icon size="12" color="#fdba74">mdi-chevron-right</v-icon>
          <span>Performance Management</span>
          <v-icon size="12" color="#fdba74">mdi-chevron-right</v-icon>
          <span class="pga-hero__breadcrumb-active">Goal Adjustment</span>
          <v-spacer></v-spacer>
          <span class="white--text font-weight-bold">{{
            loggedInStaff.name
          }}</span>
        </div>

        <div class="pga-hero__content">
          <div class="pga-hero__left">
            <div class="pga-hero__badge">
              <v-icon size="14" color="#f97316">mdi-auto-fix</v-icon>
              Mid-Year Goal Adjustment
            </div>
            <div class="pga-hero__title-row">
              <h1 class="pga-hero__title">
                {{ performancePlan ? performancePlan.name : "Goal Adjustment" }}
              </h1>
            </div>
            <div class="pga-hero__meta">
              <div class="pga-hero__meta-item">
                <v-icon size="15" color="#fdba74">mdi-calendar</v-icon>
                <span>FY {{ selectedFiscalYear }}</span>
              </div>
              <div v-if="performancePlan" class="pga-hero__meta-sep"></div>
              <div
                v-if="performancePlan"
                class="pga-hero__status"
                :class="'pga-hero__status--' + adjustmentStatus"
              >
                {{ adjustmentStatusLabel }}
              </div>
            </div>
          </div>

          <div class="pga-hero__right" v-if="performancePlan">
            <div class="pga-hero__stats">
              <div class="pga-hero__stat">
                <div class="pga-hero__stat-num pga-hero__stat-num--red">
                  {{ pendingDropsCount }}
                </div>
                <div class="pga-hero__stat-label">Drops</div>
              </div>
              <div class="pga-hero__stat-div"></div>
              <div class="pga-hero__stat">
                <div class="pga-hero__stat-num pga-hero__stat-num--amber">
                  {{ pendingModifiesCount }}
                </div>
                <div class="pga-hero__stat-label">Replaces</div>
              </div>
              <div class="pga-hero__stat-div"></div>
              <div class="pga-hero__stat">
                <div class="pga-hero__stat-num pga-hero__stat-num--green">
                  {{ pendingAddsCount }}
                </div>
                <div class="pga-hero__stat-label">Adds</div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </header>

    <!-- Main Body -->
    <div class="pga-body">
      <!-- Gate: window closed -->
      <div v-if="!loading && !midYearWindowOpen" class="pga-gate">
        <div class="pga-gate__icon-wrap pga-gate__icon-wrap--muted">
          <v-icon size="44" color="#64748b">mdi-calendar-lock</v-icon>
        </div>
        <h2 class="pga-gate__title">Adjustment Window Closed</h2>
        <p class="pga-gate__desc">
          Goal adjustments may only be made while the mid-year review window is
          open. The window has closed for FY {{ selectedFiscalYear }}.
        </p>
      </div>

      <!-- Gate: Joint S1 review must be complete -->
      <div
        v-else-if="!loading && midYearWindowOpen && !jointS1Complete"
        class="pga-gate"
      >
        <div class="pga-gate__icon-wrap">
          <v-icon size="44" color="#f97316">mdi-lock-clock</v-icon>
        </div>
        <h2 class="pga-gate__title">Complete Mid-Year Review First</h2>
        <p class="pga-gate__desc">
          Goal adjustment is only available after the joint mid-year review for
          <strong>FY {{ selectedFiscalYear }}</strong> has been completed.
          Please ensure all Semester 1 reviews are finalised before making
          adjustments.
        </p>
        <button class="pga-btn pga-btn--outline" @click="goHome">
          <v-icon left size="16">mdi-clipboard-check-outline</v-icon>
          Go Back
        </button>
      </div>

      <!-- Gate: not submitted — non-owners blocked -->
      <div
        v-else-if="!loading && performancePlan && !isOwner && isNotYetSubmitted"
        class="pga-gate"
      >
        <div class="pga-gate__icon-wrap pga-gate__icon-wrap--muted">
          <v-icon size="44" color="#64748b">mdi-eye-off-outline</v-icon>
        </div>
        <h2 class="pga-gate__title">Not Available Yet</h2>
        <p class="pga-gate__desc">
          This goal adjustment is not yet visible to you. It will become
          accessible once the staff member submits it for review.
        </p>
      </div>

      <!-- Gate: no plan -->
      <div v-else-if="!loading && !performancePlan" class="pga-gate">
        <div class="pga-gate__icon-wrap pga-gate__icon-wrap--muted">
          <v-icon size="44" color="#64748b">mdi-file-document-outline</v-icon>
        </div>
        <h2 class="pga-gate__title">No Performance Plan</h2>
        <p class="pga-gate__desc">
          You don't have a performance plan for FY {{ selectedFiscalYear }}.
        </p>
      </div>

      <!-- Status banner -->
      <v-alert
        v-if="performancePlan && statusBanner"
        :type="statusBanner.type"
        outlined
        dense
        class="pga-status-alert"
      >
        <v-icon small left>{{ statusBanner.icon }}</v-icon>
        <strong>{{ statusBanner.title }}</strong>
        {{ statusBanner.text }}
      </v-alert>

      <!-- Main content -->
      <div v-if="canShowContent" class="pga-content">
        <!-- Toolbar -->
        <div class="pga-toolbar">
          <div class="pga-toolbar__left">
            <div class="pga-toolbar__crumb">
              <v-icon size="14" color="#f97316">mdi-target</v-icon>
              <span>{{ objectives.length }} Objectives</span>
            </div>
            <div class="pga-toolbar__crumb">
              <v-icon size="14" color="#6366f1">mdi-run-fast</v-icon>
              <span>{{ activities.length }} Activities</span>
            </div>
            <div class="pga-toolbar__crumb">
              <v-icon size="14" color="#6366f1">mdi-chart-bar</v-icon>
              <span>{{ kpis.length }} KPIs</span>
            </div>
          </div>
          <div class="pga-toolbar__right">
            <div v-if="hasPendingChanges" class="pga-pending-summary-chip">
              <v-icon size="13" color="#6366f1">mdi-playlist-edit</v-icon>
              {{ totalPendingChanges }} pending change{{
                totalPendingChanges !== 1 ? "s" : ""
              }}
            </div>
            <button
              v-if="canEdit && hasPendingChanges"
              class="pga-btn pga-btn--primary pga-btn--sm"
              :disabled="submitting || !canSubmit"
              @click="openSubmitDialog"
            >
              <v-icon left size="14">mdi-send</v-icon>
              {{ isRevision ? "Resubmit" : "Submit for Review" }}
            </button>
            <button
              v-if="canEdit"
              class="pga-btn pga-btn--outline pga-btn--sm"
              @click="openAddDialog('objective', null)"
            >
              <v-icon left size="14">mdi-plus</v-icon>
              Add Objective
            </button>
          </div>
        </div>

        <!-- CTA when no pending changes -->
        <div v-if="!hasPendingChanges && canEdit" class="pga-cta">
          <v-icon size="28" color="#6366f1">mdi-pencil-ruler</v-icon>
          <div class="pga-cta__text">
            <div class="pga-cta__title">
              Review your plan and propose changes
            </div>
            <div class="pga-cta__sub">
              Drop goals that are no longer relevant, modify goals that need to
              change, or add new goals that emerged from the mid-year review.
              Each change requires a reason.
            </div>
          </div>
        </div>

        <!-- HOW-TO GUIDE NOTE -->
        <div v-if="canEdit" class="pga-guide">
          <div class="pga-guide__head">
            <v-icon size="15" color="#0891b2">mdi-information-outline</v-icon>
            <span class="pga-guide__title">How Goal Adjustment Works</span>
          </div>
          <div class="pga-guide__items">
            <v-row>
              <v-col cols="4">
                <!-- Edit / Replace -->
                <div class="pga-guide__item pga-guide__item--amber">
                  <div class="pga-guide__item-icon">
                    <v-icon size="15" color="#d97706"
                      >mdi-pencil-circle-outline</v-icon
                    >
                  </div>
                  <div class="pga-guide__item-body">
                    <div class="pga-guide__item-label">
                      <v-icon size="11" color="#d97706"
                        >mdi-pencil-outline</v-icon
                      >
                      Edit / Replace a Goal
                    </div>
                    <div class="pga-guide__item-text">
                      Click the <strong>edit (pencil)</strong> button to
                      <strong>replace</strong> an existing goal with a new
                      version. The original goal is dropped and superseded — use
                      this when a goal needs to change direction, wording or
                      targets.
                    </div>
                  </div>
                </div>
              </v-col>
              <v-col cols="4">
                <!-- Drop -->
                <div class="pga-guide__item pga-guide__item--red">
                  <div class="pga-guide__item-icon">
                    <v-icon size="15" color="#ef4444"
                      >mdi-delete-circle-outline</v-icon
                    >
                  </div>
                  <div class="pga-guide__item-body">
                    <div class="pga-guide__item-label">
                      <v-icon size="11" color="#ef4444"
                        >mdi-delete-outline</v-icon
                      >
                      Delete / Drop a Goal
                    </div>
                    <div class="pga-guide__item-text">
                      Click the <strong>delete (trash)</strong> button to
                      <strong>drop</strong> a goal entirely with no replacement.
                      Dropping an objective will cascade and drop all its
                      activities, sub-activities, KPIs and targets. Use only
                      when a goal is no longer relevant.
                    </div>
                  </div>
                </div>
              </v-col>
              <v-col cols="4">
                <!-- Add new -->
                <div class="pga-guide__item pga-guide__item--emerald">
                  <div class="pga-guide__item-icon">
                    <v-icon size="15" color="#059669"
                      >mdi-plus-circle-outline</v-icon
                    >
                  </div>
                  <div class="pga-guide__item-body">
                    <div class="pga-guide__item-label">
                      <v-icon size="11" color="#059669">mdi-plus</v-icon>
                      Add a New Independent Goal
                    </div>
                    <div class="pga-guide__item-text">
                      Click the <strong>add (+)</strong> button to propose a
                      <strong>brand new goal</strong> that is not a replacement
                      for any existing goal. <br />If you want to
                      <em>replace</em> an existing goal, use the
                      <strong>edit</strong> button instead — not add.
                    </div>
                  </div>
                </div>
              </v-col>
            </v-row>
          </div>
        </div>

        <!-- Pending changes summary panel -->
        <div
          v-if="hasPendingChanges"
          class="pga-summary"
          :class="{ 'pga-summary--readonly': !canEdit }"
        >
          <div class="pga-summary__head">
            <v-icon size="16" color="#6366f1">mdi-playlist-edit</v-icon>
            <span class="pga-summary__title">
              {{ totalPendingChanges }} proposed change{{
                totalPendingChanges !== 1 ? "s" : ""
              }}
            </span>
          </div>
          <div class="pga-summary__list">
            <div
              v-for="adj in adjustments"
              :key="adj.id"
              class="pga-summary__row"
              :class="'pga-summary__row--' + adj.adjustmentType"
            >
              <div class="pga-summary__row-left">
                <div
                  class="pga-summary__chip"
                  :class="'pga-summary__chip--' + adj.adjustmentType"
                >
                  <v-icon size="11" :color="chipIconColor(adj.adjustmentType)">
                    {{ chipIcon(adj.adjustmentType) }}
                  </v-icon>
                  {{ chipLabel(adj.adjustmentType) }}
                </div>
                <div class="pga-summary__desc">
                  <span class="pga-summary__goal-type">{{
                    resolveGoalType(adj)
                  }}</span>
                  <span class="pga-summary__goal-name">{{
                    resolveGoalName(adj)
                  }}</span>
                </div>
              </div>
              <button
                v-if="canEdit"
                class="pga-summary__remove"
                title="Undo this change"
                @click="confirmUndoAdjustment(adj)"
              >
                <v-icon size="14" color="#94a3b8">mdi-close</v-icon>
              </button>
            </div>
          </div>
        </div>

        <div
          v-if="hasPendingChanges && adjustedPlanErrors.length > 0"
          class="pga-validation-panel"
        >
          <div class="pga-validation-panel__head">
            <v-icon size="16" color="#dc2626">mdi-alert-circle</v-icon>
            <span>
              {{ adjustedPlanErrors.length }} issue{{
                adjustedPlanErrors.length !== 1 ? "s" : ""
              }}
              to fix before submitting
            </span>
          </div>
          <div class="pga-validation-panel__body">
            <div
              v-if="adjustmentGeneralErrors.length"
              class="pga-validation-obj"
            >
              <div class="pga-validation-obj__title">
                <v-icon size="13" color="#dc2626">mdi-clipboard-alert</v-icon>
                Plan requirements
              </div>
              <ul class="pga-validation-obj__errors">
                <li
                  v-for="(err, i) in adjustmentGeneralErrors"
                  :key="`plan-${i}`"
                >
                  {{ err.message }}
                </li>
              </ul>
            </div>
            <div
              v-for="oc in adjustmentObjectivesWithErrors"
              :key="oc.objective.id"
              class="pga-validation-obj"
            >
              <div class="pga-validation-obj__title">
                <v-icon size="13" color="#dc2626">mdi-target</v-icon>
                {{ oc.objective.name }}
              </div>
              <ul class="pga-validation-obj__errors">
                <li v-for="(err, i) in oc.errors" :key="i">
                  {{ err.message }}
                </li>
              </ul>
            </div>
          </div>
        </div>

        <!-- Objectives Cards Grid -->
        <div class="pga-objectives">
          <div
            v-for="(col, ci) in objectiveColumns"
            :key="ci"
            class="pga-objectives__col"
          >
            <div
              v-for="(obj, oi) in col"
              :key="obj.id"
              class="pga-obj-card"
              :class="objCardClasses(obj)"
            >
              <!-- Card Header (coloured gradient) -->
              <div
                class="pga-obj-card__header"
                :style="{
                  background: objGradient(
                    oi + ci * Math.ceil(objectives.length / 2),
                  ),
                }"
              >
                <!-- top row: number + badges + actions -->
                <div class="pga-obj-card__header-top">
                  <span class="pga-obj-card__num">
                    {{ String(globalObjectiveIndex(obj) + 1).padStart(2, "0") }}
                  </span>
                  <div class="pga-obj-card__badges">
                    <!-- Lifecycle badge -->
                    <span
                      v-if="
                        obj.lifecycleStatus &&
                          obj.lifecycleStatus !== 'original-active'
                      "
                      class="pga-lc-chip"
                      :class="'pga-lc-chip--' + obj.lifecycleStatus"
                    >
                      <v-icon
                        v-if="obj.lifecycleStatus === 'original-dropped'"
                        size="10"
                        color="#fca5a5"
                        >mdi-close-octagon</v-icon
                      >
                      <v-icon v-else size="10" color="#6ee7b7"
                        >mdi-star-four-points</v-icon
                      >
                      {{
                        obj.lifecycleStatus === "original-dropped"
                          ? "Dropped"
                          : "New"
                      }}
                    </span>
                    <!-- Adjustment badge -->
                    <span
                      v-if="adjustmentForGoal(obj)"
                      class="pga-adj-badge"
                      :class="
                        'pga-adj-badge--' +
                          adjustmentForGoal(obj).adjustmentType
                      "
                    >
                      <v-icon
                        size="10"
                        :color="
                          chipIconColor(adjustmentForGoal(obj).adjustmentType)
                        "
                      >
                        {{ chipIcon(adjustmentForGoal(obj).adjustmentType) }}
                      </v-icon>
                      {{ chipLabel(adjustmentForGoal(obj).adjustmentType) }}
                      Proposed
                    </span>
                  </div>
                  <div class="pga-obj-card__header-actions">
                    <button
                      v-if="canEdit && dropAdjForGoal(obj)"
                      class="pga-obj-action-btn"
                      title="Undo this drop"
                      @click="confirmUndoAdjustment(dropAdjForGoal(obj))"
                    >
                      <v-icon size="13" color="rgba(255,255,255,0.7)"
                        >mdi-undo</v-icon
                      >
                    </button>
                    <button
                      v-if="
                        canEdit &&
                          !isGoalDropped(obj) &&
                          !isProposedDrop(obj) &&
                          !replaceAdjForGoal(obj)
                      "
                      class="pga-obj-action-btn"
                      title="Modify / Replace this objective"
                      :disabled="
                        isGoalAddedAtMidyear(obj) && !!adjustmentForGoal(obj)
                      "
                      @click="openModifyDialog(obj, 'objective')"
                    >
                      <v-icon size="13" color="rgba(255,255,255,0.7)"
                        >mdi-pencil-outline</v-icon
                      >
                    </button>
                    <button
                      v-if="
                        canEdit &&
                          !isGoalDropped(obj) &&
                          !isProposedDrop(obj) &&
                          !replaceAdjForGoal(obj)
                      "
                      class="pga-obj-action-btn pga-obj-action-btn--danger"
                      title="Drop this objective (no replacement)"
                      @click="openDropDialog(obj, 'objective')"
                    >
                      <v-icon size="13" color="rgba(255,100,100,0.9)"
                        >mdi-delete-outline</v-icon
                      >
                    </button>
                  </div>
                </div>

                <!-- Title and description -->
                <div class="pga-obj-card__title">{{ obj.name }}</div>
                <div v-if="obj.description" class="pga-obj-card__desc">
                  {{ obj.description }}
                </div>
                <!-- Linked supervisor target -->
                <div
                  v-if="
                    obj.parentActivityId &&
                      supervisorActivityName(obj.parentActivityId)
                  "
                  class="pga-obj-card__linked-target"
                >
                  <v-icon size="12" color="rgba(94,234,212,0.8)"
                    >mdi-link-variant</v-icon
                  >
                  <div>
                    <div class="pga-obj-card__linked-target-label">
                      Supervisor Activity
                    </div>
                    <div class="pga-obj-card__linked-target-name">
                      {{ supervisorActivityName(obj.parentActivityId) }}
                    </div>
                  </div>
                </div>
                <div
                  v-else-if="
                    obj.parentActivityId &&
                      !supervisorActivityName(obj.parentActivityId)
                  "
                  class="pga-obj-card__linked-target pga-obj-card__linked-target--unresolved"
                >
                  <v-icon size="12" color="rgba(251,191,36,0.7)"
                    >mdi-link-variant</v-icon
                  >
                  <span>Linked to supervisor target (resolving…)</span>
                </div>
                <div
                  v-else-if="!obj.parentActivityId && !isGoalDropped(obj)"
                  class="pga-obj-card__linked-target pga-obj-card__linked-target--none"
                >
                  <v-icon size="12" color="rgba(255,180,100,0.6)"
                    >mdi-link-variant-off</v-icon
                  >
                  <span>Not linked to any supervisor target</span>
                </div>

                <!-- Pending reason — drop & add only -->
                <div
                  v-if="
                    adjustmentForGoal(obj) &&
                      adjustmentForGoal(obj).adjustmentType !== 'replace'
                  "
                  class="pga-obj-card__pending-reason"
                  :class="
                    'pga-obj-card__pending-reason--' +
                      adjustmentForGoal(obj).adjustmentType
                  "
                >
                  <v-icon
                    size="11"
                    :color="
                      pendingReasonIconColor(
                        adjustmentForGoal(obj).adjustmentType,
                      )
                    "
                  >
                    {{ chipIcon(adjustmentForGoal(obj).adjustmentType) }}
                  </v-icon>
                  <span class="pga-obj-card__pending-label"
                    >{{
                      pendingReasonLabel(adjustmentForGoal(obj).adjustmentType)
                    }}:</span
                  >
                  <span class="pga-obj-card__pending-text">{{
                    adjustmentForGoal(obj).reason
                  }}</span>
                </div>

                <!-- Replace diff panel — shows both title + description old → new -->
                <div v-if="replaceAdjForGoal(obj)" class="pga-replace-panel">
                  <div class="pga-replace-panel__head">
                    <v-icon size="12" color="#fbbf24"
                      >mdi-swap-horizontal</v-icon
                    >
                    <span>Replaced with</span>
                    <button
                      v-if="canEdit"
                      class="pga-replace-panel__undo"
                      @click="confirmUndoAdjustment(replaceAdjForGoal(obj).adj)"
                    >
                      <v-icon size="11">mdi-undo</v-icon> Undo
                    </button>
                  </div>
                  <div class="pga-replace-panel__diff">
                    <div class="pga-replace-panel__col">
                      <div
                        class="pga-replace-panel__col-label pga-replace-panel__col-label--old"
                      >
                        <v-icon size="10" color="#fca5a5"
                          >mdi-archive-outline</v-icon
                        >
                        Current
                      </div>
                      <div
                        class="pga-replace-panel__name pga-replace-panel__name--old"
                      >
                        {{ obj.name }}
                      </div>
                      <div
                        v-if="obj.description"
                        class="pga-replace-panel__desc pga-replace-panel__desc--old"
                      >
                        {{ obj.description }}
                      </div>
                    </div>
                    <div class="pga-replace-panel__arrow">
                      <v-icon size="20" color="#fbbf24"
                        >mdi-arrow-right-bold</v-icon
                      >
                    </div>
                    <div
                      v-if="replaceAdjForGoal(obj).newGoal"
                      class="pga-replace-panel__col"
                    >
                      <div
                        class="pga-replace-panel__col-label pga-replace-panel__col-label--new"
                      >
                        <v-icon size="10" color="#6ee7b7"
                          >mdi-star-four-points</v-icon
                        >
                        Proposed
                        <button
                          v-if="canEdit"
                          class="pga-obj-action-btn ml-1"
                          title="Edit proposed replacement"
                          style="display:inline-flex;vertical-align:middle"
                          @click="
                            openModifyDialog(
                              replaceAdjForGoal(obj).newGoal,
                              'objective',
                            )
                          "
                        >
                          <v-icon size="11" color="rgba(255,255,255,0.7)"
                            >mdi-pencil-outline</v-icon
                          >
                        </button>
                      </div>
                      <div
                        class="pga-replace-panel__name pga-replace-panel__name--new"
                      >
                        {{ replaceAdjForGoal(obj).newGoal.name }}
                      </div>
                      <div
                        v-if="replaceAdjForGoal(obj).newGoal.description"
                        class="pga-replace-panel__desc pga-replace-panel__desc--new"
                      >
                        {{ replaceAdjForGoal(obj).newGoal.description }}
                      </div>
                    </div>
                  </div>
                  <div class="pga-replace-panel__reason">
                    <v-icon size="11" color="rgba(255,220,100,0.6)"
                      >mdi-message-outline</v-icon
                    >
                    <span>{{ replaceAdjForGoal(obj).adj.reason }}</span>
                  </div>
                </div>
              </div>

              <!-- Card Body: Activities -->
              <div class="pga-obj-card__body">
                <div
