            </span>
          </div>
          <v-form ref="addFormRef" v-model="addFormValid">
            <div class="pga-field">
              <label class="pga-field__label"
                >Title <span class="red--text">*</span></label
              >
              <v-text-field
                v-model="addForm.name"
