      <div class="pga-dialog__inner">
        <div class="pga-dialog__head">
          <div class="pga-dialog__head-icon pga-dialog__head-icon--amber">
            <v-icon color="white" size="20">mdi-pencil-outline</v-icon>
          </div>
          <div>
            <div class="pga-dialog__title">
              {{
                modifyForm.goal && isGoalAddedAtMidyear(modifyForm.goal)
                  ? "Edit " + goalTypeLabel(modifyForm.goalType)
                  : "Replace " + goalTypeLabel(modifyForm.goalType)
