            </div>
            <div class="pga-dialog__sub">
              {{
                modifyForm.goal && isGoalAddedAtMidyear(modifyForm.goal)
                  ? "Update the proposed goal details and reason."
                  : "The original goal is preserved for S1 scoring; the new version applies from S2."
              }}
            </div>
          </div>
          <button class="pga-dialog__x" @click="modifyDialog = false">
            <v-icon size="18" color="#94a3b8">mdi-close</v-icon>
          </button>
        </div>
        <div class="pga-dialog__body">
          <div class="pga-modify-grid">
            <div class="pga-modify-col">
              <div class="pga-modify-col__label">
                <v-icon size="12" color="#94a3b8">mdi-archive-outline</v-icon>
                Current
              </div>
              <div class="pga-goal-preview pga-goal-preview--muted">
                <div class="pga-goal-preview__name">
                  {{ modifyForm.oldName }}
                </div>
                <div v-if="modifyForm.oldDesc" class="pga-goal-preview__desc">
                  {{ modifyForm.oldDesc }}
                </div>
              </div>
            </div>
            <div class="pga-modify-arrow">
              <v-icon size="20" color="#d97706">mdi-arrow-right-thick</v-icon>
            </div>
            <div class="pga-modify-col">
              <div class="pga-modify-col__label">
                <v-icon size="12" color="#059669">mdi-sparkles</v-icon>
                Proposed Replacement
              </div>
              <v-form ref="modifyFormRef" v-model="modifyFormValid">
                <v-text-field
                  v-model="modifyForm.name"
                  :rules="[rules.required]"
                  outlined
                  dense
                  hide-details="auto"
                  placeholder="New title"
                  class="mb-2"
                />
                <v-textarea
                  v-model="modifyForm.description"
                  outlined
                  dense
                  hide-details="auto"
                  rows="2"
                  placeholder="New description"
                />
              </v-form>
            </div>
          </div>
          <div class="pga-field mt-3">
            <label class="pga-field__label"
              >Reason for change <span class="red--text">*</span></label
            >
            <v-textarea
              v-model="modifyForm.reason"
              :rules="[rules.required]"
              outlined
              dense
              hide-details="auto"
              rows="2"
              placeholder="Why is this change needed?"
            />
