        <div class="pga-dialog__head">
          <div class="pga-dialog__head-icon pga-dialog__head-icon--neutral">
            <v-icon color="white" size="20">mdi-undo</v-icon>
          </div>
          <div>
            <div class="pga-dialog__title">Undo this change?</div>
            <div class="pga-dialog__sub">
              This removes the proposed adjustment.
            </div>
          </div>
        </div>
        <div class="pga-dialog__foot">
          <button class="pga-btn pga-btn--ghost" @click="undoDialog = false">
