            @click="confirmUndo"
          >
            <v-icon left size="14">mdi-undo</v-icon>
            Undo
          </button>
        </div>
      </div>
    </v-dialog>

    <!-- SUBMIT Dialog -->
    <v-dialog v-model="submitDialog" max-width="460" content-class="pga-dialog">
      <div class="pga-dialog__strip pga-dialog__strip--orange"></div>
      <div class="pga-dialog__inner">
        <div class="pga-dialog__head">
          <div class="pga-dialog__head-icon pga-dialog__head-icon--orange">
            <v-icon color="white" size="20">mdi-send</v-icon>
          </div>
          <div>
            <div class="pga-dialog__title">
              {{ isRevision ? "Resubmit adjustment?" : "Submit adjustment?" }}
            </div>
            <div class="pga-dialog__sub">
              {{ totalPendingChanges }} proposed change{{
                totalPendingChanges !== 1 ? "s" : ""
              }}
              will go to your supervisor, then to the HOD for approval. Once
              approved, adjusted goals will be used for Semester 2 reviews.
            </div>
          </div>
          <button class="pga-dialog__x" @click="submitDialog = false">
            <v-icon size="18" color="#94a3b8">mdi-close</v-icon>
          </button>
        </div>
        <div class="pga-dialog__foot">
          <button class="pga-btn pga-btn--ghost" @click="submitDialog = false">
            Cancel
          </button>
          <button
            class="pga-btn pga-btn--primary"
            :disabled="submitting || !canSubmit"
            @click="confirmSubmit"
          >
            <v-icon left size="14">mdi-send</v-icon>
            {{ isRevision ? "Resubmit" : "Submit" }}
          </button>
        </div>
      </div>
    </v-dialog>

    <!-- Snackbar -->
    <v-snackbar
      v-model="snackbar"
      :color="snackbarColor"
      :timeout="3500"
      bottom
      right
    >
      <div class="d-flex align-center">
        <v-icon left>{{ snackbarIcon }}</v-icon>
        {{ snackbarMessage }}
      </div>
    </v-snackbar>
