</template>

<script>
import generalMixin from "../../mixins/general";
import processQuestionnaire from "../../mixins/processQuestionnaire";

export default {
  name: "PerformancePlanAdjustment",
  mixins: [generalMixin, processQuestionnaire],

  data() {
    return {
      url: "http://ihris.org/fhir/Questionnaire/goal-adjustment",
      fhir: {},
      profile:
        "http://ihris.org/fhir/StructureDefinition/goal-adjustment-profile",

      loading: false,
      saving: false,
      submitting: false,

      selectedFiscalYear: "",
      currentFiscalYear: "",
      perfConfig: null,

      performancePlan: null,
      objectives: [],
      activities: [],
      subActivities: [],
      kpis: [],
      targets: [],
      supervisorActivities: [],
      loadingSupervisorActivities: false,

      adjustments: [],
      reviews: [],
      expandedReviews: {},

      dropDialog: false,
      dropForm: {
        goal: null,
        goalType: "",
        goalName: "",
        goalDesc: "",
        reason: "",
      },

      addDialog: false,
      addForm: {
        goalType: "",
        parent: null,
        parentName: "",
        name: "",
        description: "",
        reason: "",
        parentActivityId: null,
      },
      addFormValid: false,

      modifyDialog: false,
      modifyForm: {
        goal: null,
        goalType: "",
        oldName: "",
        oldDesc: "",
        name: "",
        description: "",
        reason: "",
        adjustmentId: null,
        existingAdj: null,
      },
      modifyFormValid: false,

      undoDialog: false,
      undoTarget: null,

      submitDialog: false,

      snackbar: false,
      snackbarMessage: "",
      snackbarColor: "success",
      snackbarIcon: "mdi-check-circle",

      rules: {
        required: (v) => (!!v && String(v).trim() !== "") || "Required",
      },

      gradients: [
        "linear-gradient(135deg,#1e3a5f 0%,#2563eb 100%)",
        "linear-gradient(135deg,#1e4d3a 0%,#059669 100%)",
        "linear-gradient(135deg,#4c1d95 0%,#7c3aed 100%)",
        "linear-gradient(135deg,#7c2d12 0%,#f97316 100%)",
        "linear-gradient(135deg,#164e63 0%,#0891b2 100%)",
        "linear-gradient(135deg,#3b0764 0%,#a21caf 100%)",
        "linear-gradient(135deg,#134e4a 0%,#0d9488 100%)",
        "linear-gradient(135deg,#1e1b4b 0%,#6366f1 100%)",
      ],
    };
  },

  computed: {
    queries() {
      return (this.$route && this.$route.query) || {};
    },
    adjustmentStatus() {
      return (
        (this.performancePlan && this.performancePlan.adjustmentStatus) ||
        "draft"
      );
    },
    adjustmentStatusLabel() {
      const map = {
        draft: "Draft",
        submitted: "Submitted",
        "supervisor-approved": "Supervisor Approved",
        "supervisor-rejected": "Supervisor Rejected",
        "hod-approved": "HOD Approved",
        "hod-rejected": "HOD Rejected",
        approved: "Approved",
      };
      return map[this.adjustmentStatus] || this.adjustmentStatus;
    },
    jointS1Complete() {
      return this.performancePlan?.jointPeriod1Status === "submitted";
    },
    midYearWindowOpen() {
      if (!this.perfConfig) return true; // still loading — optimistic
      return this.perfConfig["mid-year-review"]?.isOpen ?? false;
    },
    isOwner() {
      return this.queries.practitioner === this.loggedInStaff.practitioner;
    },
    isNotYetSubmitted() {
      return ["draft", "supervisor-rejected", "hod-rejected"].includes(
        this.adjustmentStatus,
      );
    },
    canEdit() {
      if (!this.isOwner) return false;
      if (!this.jointS1Complete || !this.midYearWindowOpen) return false;
      return ["draft", "supervisor-rejected", "hod-rejected"].includes(
        this.adjustmentStatus,
      );
    },
    isRevision() {
      return ["supervisor-rejected", "hod-rejected"].includes(
        this.adjustmentStatus,
      );
    },
    canShowContent() {
      return (
        !this.loading &&
        this.performancePlan &&
        this.jointS1Complete &&
        this.midYearWindowOpen &&
        (this.isOwner || !this.isNotYetSubmitted)
      );
    },
    statusBanner() {
      if (this.adjustmentStatus === "submitted")
        return {
          type: "info",
          icon: "mdi-clock-outline",
          title: "Awaiting supervisor review.",
          text: "You cannot edit while under review.",
        };
      if (this.adjustmentStatus === "supervisor-approved")
        return {
          type: "info",
          icon: "mdi-clock-outline",
          title: "Awaiting HOD review.",
          text: "Changes are frozen.",
        };
      if (this.adjustmentStatus === "supervisor-rejected")
        return {
          type: "warning",
          icon: "mdi-alert-circle-outline",
          title: "Supervisor rejected.",
          text: "Review comments and resubmit.",
        };
      if (this.adjustmentStatus === "hod-rejected")
        return {
          type: "warning",
          icon: "mdi-alert-circle-outline",
          title: "HOD rejected.",
          text: "Review comments and resubmit.",
        };
      if (this.adjustmentStatus === "hod-approved")
        return {
          type: "success",
          icon: "mdi-check-circle-outline",
          title: "Adjustment applied",
          text: "Adjusted goals will take effect for Semester 2.",
        };
      return null;
    },
    pendingDropsCount() {
      return this.adjustments.filter((a) => a.adjustmentType === "drop").length;
    },
    pendingModifiesCount() {
      return this.adjustments.filter((a) => a.adjustmentType === "replace")
        .length;
    },
    pendingAddsCount() {
      return this.adjustments.filter((a) => a.adjustmentType === "add").length;
    },
    adjustedObjectives() {
      return this.buildAdjustedGoalList(this.objectives, null);
    },
    adjustmentGeneralErrors() {
      const errors = [];
      if (this.hasPendingChanges && this.adjustedObjectives.length === 0) {
        errors.push({
          level: "plan",
          message:
            "At least one objective is required after applying these changes.",
        });
      }
      return errors;
    },
    adjustmentObjectiveCompleteness() {
      return this.adjustedObjectives.map((obj) => {
        const errors = [];
        const activities = this.getAdjustedActivities(obj.id);
        if (activities.length === 0) {
          errors.push({
            level: "objective",
            id: obj.id,
            message: "At least one activity is required",
          });
        }
        for (const act of activities) {
          const subs = this.getAdjustedSubActivities(act.id);
          if (subs.length === 0) {
            const kpis = this.getAdjustedKpis(act.id);
            if (kpis.length === 0) {
              errors.push({
                level: "activity",
                id: act.id,
                message: `"${act.name}": needs at least one KPI`,
              });
            }
            for (const kpi of kpis) {
              if (!this.getAdjustedTargetForKpi(kpi.id)) {
                errors.push({
                  level: "kpi",
                  id: kpi.id,
                  activityId: act.id,
                  message: `"${act.name}" › KPI "${kpi.name}": missing target`,
                });
              }
            }
          } else {
            for (const sub of subs) {
              const kpis = this.getAdjustedKpis(sub.id);
              if (kpis.length === 0) {
                errors.push({
                  level: "subactivity",
                  id: sub.id,
                  activityId: act.id,
                  message: `"${act.name}" › "${sub.name}": needs at least one KPI`,
                });
              }
              for (const kpi of kpis) {
                if (!this.getAdjustedTargetForKpi(kpi.id)) {
                  errors.push({
                    level: "kpi",
                    id: kpi.id,
                    activityId: act.id,
                    subId: sub.id,
                    message: `"${act.name}" › "${sub.name}" › KPI "${kpi.name}": missing target`,
                  });
                }
              }
            }
            for (const kpi of this.getAdjustedKpis(act.id)) {
              if (!this.getAdjustedTargetForKpi(kpi.id)) {
                errors.push({
                  level: "kpi",
                  id: kpi.id,
                  activityId: act.id,
                  message: `"${act.name}" › KPI "${kpi.name}": missing target`,
                });
              }
            }
          }
        }
        return { objective: obj, errors, isComplete: errors.length === 0 };
      });
    },
    adjustmentObjectivesWithErrors() {
      return this.adjustmentObjectiveCompleteness.filter(
        (oc) => oc.errors.length > 0,
      );
    },
    adjustedPlanErrors() {
      return [
        ...this.adjustmentGeneralErrors,
        ...this.adjustmentObjectiveCompleteness.flatMap((o) => o.errors),
      ];
    },
    totalPendingChanges() {
      return this.adjustments.length;
    },
    hasPendingChanges() {
      return this.adjustments.length > 0;
    },
    canSubmit() {
      return (
        this.hasPendingChanges &&
        this.canEdit &&
        this.adjustedPlanErrors.length === 0
      );
    },

    objectiveColumns() {
      const cols = [[], []];
      this.objectives
        .filter((obj) => !this.isReplacementGoal(obj))
        .forEach((obj, i) => {
          cols[i % 2].push(obj);
        });
      return cols;
    },
  },

  async mounted() {
    this.loading = true;
    await this.$nextTick();
    await new Promise((resolve) => {
      if (!this.loadingUserData) return resolve();
      const unwatch = this.$watch("loadingUserData", (v) => {
        if (!v) {
          unwatch();
          resolve();
        }
      });
      setTimeout(() => {
        unwatch();
        resolve();
      }, 15000);
    });

    if (!this.queries.practitioner) {
      this.queries.practitioner = this.loggedInStaff.practitioner;
    }

    let fy = await fetch("/site/leave/getFinancialYear");
    fy = await fy.json();
    this.selectedFiscalYear = fy.year;
    this.currentFiscalYear = fy.year;

    await this.loadPerfConfig();
    await this.initialize();

    if (this.adjustmentStatus === "hod-approved") {
      let user = this.$store.state.user?.obj?.resource?.id;
      let task = await fetch(
        `/fhir/Basic?user=${user}&usertaskstatus=pending&usertaskid=${this.queries.plan}`,
      );
      let response = await task.json();
      if (response && response.entry && response.entry.length) {
        let taskDescr = response.entry[0].resource.extension.find((ext) => {
          return (
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/user-task-description"
          );
        });
        let statusIndex = taskDescr.extension.findIndex((ext) => {
          return ext.url === "status";
        });
        taskDescr.extension[statusIndex].valueCoding.code = "done";
        taskDescr.extension[statusIndex].valueCoding.display = "Done";

        fetch("/fhir/Basic/" + response.entry[0].resource.id, {
          method: "PUT",
          headers: {
            "Content-Type": "application/fhir+json",
            Accept: "application/fhir+json",
          },
          body: JSON.stringify(response.entry[0].resource),
        });
      }
    }
  },

  methods: {
    async loadPerfConfig() {
      try {
        const [cfgRes, ovRes] = await Promise.all([
          fetch("/fhir/Parameters/performance-config").then((r) =>
            r.ok ? r.json() : null,
          ),
          fetch("/fhir/Parameters/performance-override-config").then((r) =>
            r.ok ? r.json() : null,
          ),
        ]);
        if (!cfgRes) return;
        const shift = (fy, d) => {
          const parts = fy.split("/").map(Number);
          return parts[0] + d + "/" + (parts[1] + d);
        };
        // const today = new Date("2026-09-20");
        const today = new Date();
        const todayStr =
          String(today.getMonth() + 1).padStart(2, "0") +
          "-" +
          String(today.getDate()).padStart(2, "0");
        const fraction = (mmdd) => {
          if (!mmdd) return 0;
          const parts = mmdd.split("-").map(Number);
          const mm = parts[0],
            dd = parts[1];
          const days = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
          return (
            (days.slice(0, mm - 1).reduce((a, b) => a + b, 0) + dd - 1) / 365
          );
        };
        const inRange = (s, e) => {
          const t = fraction(todayStr),
            sf = fraction(s),
            ef = fraction(e);
          return ef < sf ? t >= sf || t <= ef : t >= sf && t <= ef;
        };
        const overrides = {};
        for (const p of (ovRes && ovRes.parameter) || []) {
          const g = (n) =>
            ((p.part || []).find((pt) => pt.name === n) || {}).valueString ||
            "";
          overrides[p.name] = {
            fiscalYear: g("fiscal-year"),
            overrideEnd: g("override-end"),
            status: g("status"),
          };
        }
        const cfg = {};
        for (const p of cfgRes.parameter || []) {
          const g = (n) =>
            ((p.part || []).find((pt) => pt.name === n) || {}).valueString ||
            "";
          const ctx = g("fiscal-year-context");
          const d = ctx === "next" ? 1 : ctx === "previous" ? -1 : 0;
          const derivedTargetFY = ctx
            ? shift(this.currentFiscalYear, d)
            : this.currentFiscalYear;
          const baseOpen = inRange(g("start-date"), g("end-date"));
          const ov = overrides[p.name];
          const ovActive =
            ov && ov.status === "active" && new Date(ov.overrideEnd) >= today;
          const targetFY = ovActive ? ov.fiscalYear : derivedTargetFY;
          cfg[p.name] = {
            isOpen: baseOpen || ovActive,
            targetFY,
            context: ctx,
            hasOverride: ovActive,
          };
        }
        this.perfConfig = cfg;
        const targetFY =
          cfg["mid-year-review"] && cfg["mid-year-review"].targetFY;
        if (targetFY) this.selectedFiscalYear = targetFY;
      } catch (e) {
        console.error("loadPerfConfig error", e);
      }
    },

    async initialize() {
      try {
        await this.loadPerformancePlan();
        if (this.performancePlan) {
          await this.loadObjectives();
          await this.loadActivities();
          await this.loadSubActivities();
          await this.loadKpis();
          await this.loadTargets();
          await this.loadSupervisorActivities();
          await this.loadAdjustments();
          await this.loadReviews();
        }
      } catch (e) {
        console.error(e);
        this.showSnackbar("Error loading data", "error");
      } finally {
        this.loading = false;
      }
    },

    _ext(resource, url) {
      return (resource.extension || []).find((e) => e.url.includes(url));
    },

    async loadPerformancePlan() {
      const params = new URLSearchParams({
        _profile:
          "http://ihris.org/fhir/StructureDefinition/performance-plan-profile",
        practitioner: "Practitioner/" + this.queries.practitioner,
        fiscalyear: this.selectedFiscalYear,
      });
      const r = await fetch("/fhir/Basic?" + params);
      const b = await r.json();
      if (b.entry && b.entry.length) {
        this.performancePlan = this._extractPlan(b.entry[0].resource);
      } else {
        this.performancePlan = null;
      }
    },

    _extractPlan(r) {
      return {
        id: r.id,
        name: (this._ext(r, "ihris-basic-name") || {}).valueString || "",
        fiscalYear: (this._ext(r, "fiscal-year") || {}).valueString || "",
        status:
          ((this._ext(r, "request-status") || {}).valueCoding || {}).code ||
          "draft",
        adjustmentStatus:
          ((this._ext(r, "goal-adjustment-status") || {}).valueCoding || {})
            .code || "draft",
        jointPeriod1Status:
          (
            (this._ext(r, "joint-period1-annual-review-status") || {})
              .valueCoding || {}
          ).code || "",
      };
    },

    async loadObjectives() {
      if (!this.performancePlan) return;
      const params = new URLSearchParams({
        _profile:
          "http://ihris.org/fhir/StructureDefinition/performance-objective-profile",
        performanceplan: "Basic/" + this.performancePlan.id,
      });
      const r = await fetch("/fhir/Basic?" + params);
      const b = await r.json();
      this.objectives = b.entry
        ? b.entry.map((e) => this._extractGoal(e.resource, "objective"))
        : [];
    },

    async loadActivities() {
      if (!this.objectives.length) {
        this.activities = [];
        return;
      }
      const params = new URLSearchParams({
        _profile:
          "http://ihris.org/fhir/StructureDefinition/performance-activity-profile",
        parent: this.objectives.map((o) => o.id).join(","),
      });
      const r = await fetch("/fhir/Basic?" + params);
      const b = await r.json();
      this.activities = b.entry
        ? b.entry.map((e) => this._extractGoal(e.resource, "activity"))
        : [];
    },

    async loadSubActivities() {
      if (!this.activities.length) {
        this.subActivities = [];
        return;
      }
      const params = new URLSearchParams({
        _profile:
          "http://ihris.org/fhir/StructureDefinition/performance-subactivity-profile",
        parent: this.activities.map((a) => a.id).join(","),
      });
      const r = await fetch("/fhir/Basic?" + params);
      const b = await r.json();
      this.subActivities = b.entry
        ? b.entry.map((e) => this._extractGoal(e.resource, "subactivity"))
        : [];
    },

    async loadKpis() {
      const parentIds = [
        ...this.activities.map((a) => a.id),
        ...this.subActivities.map((s) => s.id),
      ];
      if (!parentIds.length) {
        this.kpis = [];
        return;
      }
      const params = new URLSearchParams({
        _profile:
          "http://ihris.org/fhir/StructureDefinition/performance-kpi-profile",
        parent: parentIds.join(","),
      });
      const r = await fetch("/fhir/Basic?" + params);
      const b = await r.json();
      this.kpis = b.entry
        ? b.entry.map((e) => this._extractGoal(e.resource, "kpi"))
        : [];
    },

    async loadTargets() {
      if (!this.kpis.length) {
        this.targets = [];
        return;
      }
      const params = new URLSearchParams({
        _profile:
          "http://ihris.org/fhir/StructureDefinition/performance-target-profile",
        parent: this.kpis.map((k) => k.id).join(","),
      });
      const r = await fetch("/fhir/Basic?" + params);
      const b = await r.json();
      this.targets = b.entry
        ? b.entry.map((e) => this._extractGoal(e.resource, "target"))
        : [];
    },

    _extractGoal(r, goalType) {
      const parentRef = ((this._ext(r, "parent") || {}).valueReference || {})
        .reference;
      const planRef = (
        (this._ext(r, "performance-plan-reference") || {}).valueReference || {}
      ).reference;
      const supersededRef = (
        (this._ext(r, "superseded-by-goal") || {}).valueReference || {}
      ).reference;
      const parentActRef = (
        (this._ext(r, "objective-target-reference") || {}).valueReference || {}
      ).reference;
      return {
        id: r.id,
        goalType,
        name: (this._ext(r, "ihris-basic-name") || {}).valueString || "",
        description: (this._ext(r, "description") || {}).valueString || "",
        parentId: parentRef ? parentRef.split("/")[1] : null,
        performancePlanId: planRef ? planRef.split("/")[1] : null,
        lifecycleStatus:
          ((this._ext(r, "goal-lifecycle-status") || {}).valueCoding || {})
            .code || "original-active",
        supersededById: supersededRef ? supersededRef.split("/")[1] : null,
        parentActivityId: parentActRef ? parentActRef.split("/")[1] : null,
      };
    },

    async loadSupervisorActivities() {
      this.loadingSupervisorActivities = true;
      this.supervisorActivities = [];
      try {
        const supervisor = this.loggedInStaff && this.loggedInStaff.supervisor;
        if (!supervisor || !supervisor.practitioner) return;

        const planParams = new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/performance-plan-profile",
          practitioner: supervisor.practitioner,
          fiscalyear: this.selectedFiscalYear,
          _revinclude: "Basic:performanceplan",
        });
        let planResp = await fetch("/fhir/Basic?" + planParams);
        planResp = await planResp.json();
        if (!planResp.entry || !planResp.entry.length) return;

        const objectives = planResp.entry.filter((record) =>
          record.resource.meta.profile.includes(
            "http://ihris.org/fhir/StructureDefinition/performance-objective-profile",
          ),
        );
        if (!objectives.length) return;

        const objectiveIds = objectives.map((o) => o.resource.id).join(",");
        const childParams = new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/performance-objective-profile",
          _id: objectiveIds,
          practitioner: supervisor.practitioner,
          "_revinclude:iterate": "Basic:parent",
        });
        let childResp = await fetch("/fhir/Basic?" + childParams);
        childResp = await childResp.json();
        if (!childResp.entry) return;

        const getName = (resource) =>
          (resource.extension || []).find(
            (ext) =>
              ext.url ===
              "http://ihris.org/fhir/StructureDefinition/ihris-basic-name",
          )?.valueString || resource.id;

        const acts = childResp.entry.filter((r) =>
          r.resource.meta.profile.includes(
            "http://ihris.org/fhir/StructureDefinition/performance-activity-profile",
          ),
        );
        const subs = childResp.entry.filter((r) =>
          r.resource.meta.profile.includes(
            "http://ihris.org/fhir/StructureDefinition/performance-subactivity-profile",
          ),
        );

        this.supervisorActivities = [
          ...acts.map((e) => ({
            id: e.resource.id,
            name: getName(e.resource),
            displayName: getName(e.resource),
            type: "activity",
          })),
          ...subs.map((e) => ({
            id: e.resource.id,
            name: getName(e.resource),
            displayName: "↳ " + getName(e.resource),
            type: "sub-activity",
          })),
        ];

        const loadedIds = new Set(this.supervisorActivities.map((a) => a.id));
        for (const obj of this.objectives) {
          if (obj.parentActivityId && !loadedIds.has(obj.parentActivityId)) {
            await this._fetchSupervisorActivityById(obj.parentActivityId);
          }
        }
      } catch (e) {
        console.error("loadSupervisorActivities error", e);
      } finally {
        this.loadingSupervisorActivities = false;
      }
    },

    async _fetchSupervisorActivityById(activityId) {
      try {
        const r = await fetch(`/fhir/Basic/${activityId}`);
        if (!r.ok) return;
        const resource = await r.json();
        const getName = (res) =>
          (res.extension || []).find(
            (ext) =>
              ext.url ===
              "http://ihris.org/fhir/StructureDefinition/ihris-basic-name",
          )?.valueString || res.id;
        const isSubActivity = (resource.meta?.profile || []).some((p) =>
          p.includes("performance-subactivity-profile"),
        );
        const already = this.supervisorActivities.find(
          (a) => a.id === resource.id,
        );
        if (!already) {
          this.supervisorActivities.push({
            id: resource.id,
            name: getName(resource),
            displayName: isSubActivity
              ? "↳ " + getName(resource)
              : getName(resource),
            type: isSubActivity ? "sub-activity" : "activity",
          });
        }
      } catch (e) {
        console.error("_fetchSupervisorActivityById error", e);
      }
    },

    supervisorActivityName(id) {
      if (!id) return null;
      const found = this.supervisorActivities.find((a) => a.id === id);
      return found ? found.name : null;
    },

    async loadAdjustments() {
      if (!this.performancePlan) return;
      try {
        const params = new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/goal-adjustment-profile",
          practitioner: "Practitioner/" + this.queries.practitioner,
          _sort: "-_lastUpdated",
        });
        const r = await fetch("/fhir/Basic?" + params);
        const b = await r.json();
        const raw = (b.entry || []).map((e) =>
          this._extractAdjustment(e.resource),
        );
        const planGoalIds = new Set([
          ...this.objectives.map((o) => o.id),
          ...this.activities.map((a) => a.id),
          ...this.subActivities.map((s) => s.id),
          ...this.kpis.map((k) => k.id),
          ...this.targets.map((t) => t.id),
        ]);
        this.adjustments = raw.filter(
          (a) =>
            (a.oldGoalId && planGoalIds.has(a.oldGoalId)) ||
            (a.supersededById && planGoalIds.has(a.supersededById)),
        );
      } catch (e) {
        console.error("loadAdjustments", e);
        this.adjustments = [];
      }
    },

    _extractAdjustment(r) {
      return {
        id: r.id,
        adjustmentType:
          ((this._ext(r, "goal-adjustment-type") || {}).valueCoding || {})
            .code || "",
        oldGoalId: ((this._ext(r, "old-goal") || {}).valueReference || {})
          .reference
          ? (
              (this._ext(r, "old-goal") || {}).valueReference || {}
            ).reference.split("/")[1]
          : null,
        supersededById: (
          (this._ext(r, "superseded-by-goal") || {}).valueReference || {}
        ).reference
          ? (
              (this._ext(r, "superseded-by-goal") || {}).valueReference || {}
            ).reference.split("/")[1]
          : null,
        reason: (this._ext(r, "reason") || {}).valueString || "",
        eventDate: (this._ext(r, "event-date") || {}).valueDate || "",
      };
    },

    async loadReviews() {
      if (!this.performancePlan) return;
      const planRef = "Basic/" + this.performancePlan.id;
      const [supRes, hodRes] = await Promise.all([
        fetch(
          "/fhir/Basic?" +
            new URLSearchParams({
              _profile:
                "http://ihris.org/fhir/StructureDefinition/supervisor-goal-adjustment-review-profile",
              performanceplan: planRef,
              _sort: "-_lastUpdated",
            }),
        ).then((r) => r.json()),
        fetch(
          "/fhir/Basic?" +
            new URLSearchParams({
              _profile:
                "http://ihris.org/fhir/StructureDefinition/hod-goal-adjustment-review-profile",
              performanceplan: planRef,
              _sort: "-_lastUpdated",
            }),
        ).then((r) => r.json()),
      ]);
      const sup = (supRes.entry || []).map((e) =>
        this._extractReview(e.resource, "supervisor"),
      );
      const hod = (hodRes.entry || []).map((e) =>
        this._extractReview(e.resource, "hod"),
      );
      this.reviews = [...sup, ...hod].sort(
        (a, b) => new Date(b.date) - new Date(a.date),
      );
      if (this.reviews.length) this.$set(this.expandedReviews, 0, true);
    },

    _extractReview(r, role) {
      return {
        id: r.id,
        role,
        comment: (this._ext(r, "description") || {}).valueString || "",
        decision:
          ((this._ext(r, "review-status") || {}).valueCoding || {}).code || "",
        date: r.meta && r.meta.lastUpdated,
      };
    },

    // Helpers
    getActivities(objId) {
      return this.activities.filter((a) => a.parentId === objId);
    },
    getVisibleActivities(objId) {
      return this.getActivities(objId).filter(
        (act) => !this.isReplacementGoal(act),
      );
    },
    getSubActivities(actId) {
      return this.subActivities.filter((s) => s.parentId === actId);
    },
    getVisibleSubActivities(actId) {
      return this.getSubActivities(actId).filter(
        (sub) => !this.isReplacementGoal(sub),
      );
    },
    getKpis(parentId) {
      return this.kpis.filter((k) => k.parentId === parentId);
    },
    getVisibleKpis(parentId) {
      return this.getKpis(parentId).filter(
        (kpi) => !this.isReplacementGoal(kpi),
      );
    },
    getTargetForKpi(kpiId) {
      // Return the original (non-replacement) target for this KPI.
      // The new replacement target is rendered inside the replace diff row.
      return (
        this.targets.find(
          (t) => t.parentId === kpiId && !this.isReplacementGoal(t),
        ) || null
      );
    },
    replaceSourceAdjForGoal(goal) {
      if (!goal) return null;
      return (
        this.adjustments.find(
          (a) => a.adjustmentType === "replace" && a.supersededById === goal.id,
        ) || null
      );
    },
    isAdjustedDropped(goal) {
      return !!goal && (this.isGoalDropped(goal) || this.isProposedDrop(goal));
    },
    effectiveAdjustedParentId(goal) {
      if (!goal || !goal.parentId) return null;
      const parent = this._findGoalById(goal.parentId);
      const replacement = this.replaceAdjForGoal(parent);
      return replacement?.adj?.supersededById || goal.parentId;
    },
    belongsToAdjustedParent(goal, parentId) {
      if (!goal) return false;
      return parentId
        ? this.effectiveAdjustedParentId(goal) === parentId
        : !goal.parentId;
    },
    hasAdjustedDroppedAncestor(goal) {
      let currentId = goal?.parentId;
      let guard = 10;
      while (currentId && guard-- > 0) {
        const parent = this._findGoalById(currentId);
        if (!parent) break;
        if (this.isAdjustedDropped(parent)) return true;
        currentId = parent.parentId;
      }
      return false;
    },
    buildAdjustedGoalList(goals, parentId = null) {
      const siblings = goals.filter((goal) =>
        this.belongsToAdjustedParent(goal, parentId),
      );
      const result = [];
      const seen = new Set();

      for (const goal of siblings) {
        if (seen.has(goal.id)) continue;
        if (
          this.isAdjustedDropped(goal) ||
          this.hasAdjustedDroppedAncestor(goal)
        ) {
          seen.add(goal.id);
          continue;
        }

        const replacement = this.replaceAdjForGoal(goal);
        if (replacement) {
          const newGoal =
            replacement.newGoal ||
            this._findGoalById(replacement.adj.supersededById);
          if (
            newGoal &&
            !seen.has(newGoal.id) &&
            !this.isAdjustedDropped(newGoal) &&
            !this.hasAdjustedDroppedAncestor(newGoal) &&
            this.belongsToAdjustedParent(newGoal, parentId)
          ) {
            result.push(newGoal);
            seen.add(newGoal.id);
          }
          seen.add(goal.id);
          continue;
        }

        const replaceSource = this.replaceSourceAdjForGoal(goal);
        if (replaceSource) {
          const oldGoal = this._findGoalById(replaceSource.oldGoalId);
          if (oldGoal && this.belongsToAdjustedParent(oldGoal, parentId)) {
            seen.add(goal.id);
            continue;
          }
        }

        result.push(goal);
        seen.add(goal.id);
      }

      return result;
    },
    getAdjustedActivities(objId) {
      return this.buildAdjustedGoalList(this.activities, objId);
    },
    getAdjustedSubActivities(actId) {
      return this.buildAdjustedGoalList(this.subActivities, actId);
    },
    getAdjustedKpis(parentId) {
      return this.buildAdjustedGoalList(this.kpis, parentId);
    },
    getAdjustedTargetForKpi(kpiId) {
      return this.buildAdjustedGoalList(this.targets, kpiId)[0] || null;
    },
    globalObjectiveIndex(obj) {
      return this.objectives.indexOf(obj);
    },
    countKpisForObj(objId) {
      const actIds = this.getActivities(objId).map((a) => a.id);
      const subIds = this.subActivities
        .filter((s) => actIds.includes(s.parentId))
        .map((s) => s.id);
      return this.kpis.filter(
        (k) => actIds.includes(k.parentId) || subIds.includes(k.parentId),
      ).length;
    },

    adjustmentForGoal(goal) {
      if (!goal) return null;
      // Only match on oldGoalId — the NEW replacement goal is rendered inside
      // the old goal's diff panel, not independently flagged in the tree.
      return this.adjustments.find((a) => a.oldGoalId === goal.id) || null;
    },

    dropAdjForGoal(goal) {
      const adj = this.adjustmentForGoal(goal);
      return adj && adj.adjustmentType === "drop" ? adj : null;
    },

    // Returns { adj, newGoal } when this goal is the OLD half of a replace pair.
    replaceAdjForGoal(goal) {
      if (!goal) return null;
      const adj = this.adjustments.find(
        (a) => a.adjustmentType === "replace" && a.oldGoalId === goal.id,
      );
      if (!adj) return null;
      return {
        adj,
        newGoal: adj.supersededById
          ? this._findGoalById(adj.supersededById)
          : null,
      };
    },

    // Returns true when this goal is the NEW replacement in a replace pair.
    // Such goals are hidden from independent tree rendering.
    isReplacementGoal(goal) {
      if (!goal) return false;
      return this.adjustments.some(
        (a) => a.adjustmentType === "replace" && a.supersededById === goal.id,
      );
    },

    isGoalDropped(goal) {
      return goal.lifecycleStatus === "original-dropped";
    },
    // True when a drop adjustment has been proposed (but not yet finalised).
    isProposedDrop(goal) {
      if (!goal) return false;
      const adj = this.adjustmentForGoal(goal);
      return !!(adj && adj.adjustmentType === "drop");
    },
    isGoalAddedAtMidyear(goal) {
      return goal.lifecycleStatus === "added-at-midyear";
    },

    isCascadeDropped(goal) {
      let currentId = goal.parentId;
      let guard = 10;
      while (currentId && guard-- > 0) {
        const parent =
          this.activities.find((x) => x.id === currentId) ||
          this.subActivities.find((x) => x.id === currentId) ||
          this.objectives.find((x) => x.id === currentId);
        if (!parent) break;
        const adj = this.adjustmentForGoal(parent);
        if (adj && adj.adjustmentType === "drop") return true;
        if (parent.goalType === "objective") break;
        currentId = parent.parentId;
      }
      return false;
    },

    objGradient(i) {
      return this.gradients[i % this.gradients.length];
    },

    objCardClasses(obj) {
      const adj = this.adjustmentForGoal(obj);
      return {
        "pga-obj-card--dropped":
          this.isGoalDropped(obj) || (adj && adj.adjustmentType === "drop"),
        "pga-obj-card--replace": adj && adj.adjustmentType === "replace",
        "pga-obj-card--added":
          this.isGoalAddedAtMidyear(obj) ||
          (adj && adj.adjustmentType === "add"),
      };
    },
    actCardClasses(act) {
      const adj = this.adjustmentForGoal(act);
      return {
        "pga-activity--dropped":
          this.isGoalDropped(act) ||
          (adj && adj.adjustmentType === "drop") ||
          this.isCascadeDropped(act),
        "pga-activity--replace": adj && adj.adjustmentType === "replace",
        "pga-activity--added":
          this.isGoalAddedAtMidyear(act) ||
          (adj && adj.adjustmentType === "add"),
      };
    },
    subCardClasses(sub) {
      const adj = this.adjustmentForGoal(sub);
      return {
        "pga-sub--dropped":
          this.isGoalDropped(sub) ||
          (adj && adj.adjustmentType === "drop") ||
          this.isCascadeDropped(sub),
        "pga-sub--replace": adj && adj.adjustmentType === "replace",
        "pga-sub--added":
          this.isGoalAddedAtMidyear(sub) ||
          (adj && adj.adjustmentType === "add"),
      };
    },
    kpiRowClasses(kpi) {
      const adj = this.adjustmentForGoal(kpi);
      return {
        "pga-kpi-row--dropped": this.isGoalDropped(kpi),
        "pga-kpi-row--replace": adj && adj.adjustmentType === "replace",
        "pga-kpi-row--cascade": this.isCascadeDropped(kpi),
        "pga-kpi-row--added": this.isGoalAddedAtMidyear(kpi),
      };
    },

    chipIcon(type) {
      return type === "drop"
        ? "mdi-delete-outline"
        : type === "replace"
        ? "mdi-swap-horizontal"
        : "mdi-plus-circle-outline";
    },
    chipIconColor(type) {
      return type === "drop"
        ? "#dc2626"
        : type === "replace"
        ? "#d97706"
        : "#059669";
    },
    chipLabel(type) {
      return type === "drop" ? "Drop" : type === "replace" ? "Replace" : "Add";
    },
    pendingReasonIconColor(type) {
      return type === "drop"
        ? "rgba(255,150,150,0.9)"
        : type === "replace"
        ? "rgba(255,200,100,0.9)"
        : "rgba(110,231,183,0.9)";
    },
    pendingReasonLabel(type) {
      return type === "drop"
        ? "Proposed drop"
        : type === "replace"
        ? "Proposed replacement"
        : "Proposed add";
    },
    goalTypeLabel(type) {
      const m = {
        objective: "Objective",
        activity: "Activity",
        subactivity: "Sub-Activity",
        kpi: "KPI",
        target: "Target",
      };
      return m[type] || type;
    },
    _findGoalById(id) {
      return (
        this.objectives.find((g) => g.id === id) ||
        this.activities.find((g) => g.id === id) ||
        this.subActivities.find((g) => g.id === id) ||
        this.kpis.find((g) => g.id === id) ||
        this.targets.find((g) => g.id === id) ||
        null
      );
    },
    resolveGoalType(adj) {
      const g = this._findGoalById(adj.oldGoalId || adj.supersededById);
      return g ? this.goalTypeLabel(g.goalType) + " ·" : "·";
    },
    resolveGoalName(adj) {
      const oldG = adj.oldGoalId ? this._findGoalById(adj.oldGoalId) : null;
      const newG = adj.supersededById
        ? this._findGoalById(adj.supersededById)
        : null;

      if (adj.adjustmentType === "add") {
        return newG ? newG.name : "(unknown)";
      }

      if (!oldG) return newG ? newG.name : "(unknown)";

      if (adj.adjustmentType === "replace" && adj.supersededById) {
        return newG ? oldG.name + " → " + newG.name : oldG.name;
      }

      return oldG.name;
    },

    openDropDialog(goal, goalType) {
      this.dropForm = {
        goal,
        goalType,
        goalName: goal.name,
        goalDesc: goal.description,
        reason: "",
      };
      this.dropDialog = true;
      this.$nextTick(
        () =>
          this.$refs.dropFormRef && this.$refs.dropFormRef.resetValidation(),
      );
    },
    async confirmDrop() {
      if (!this.$refs.dropFormRef.validate()) return;
      this.saving = true;
      const isAddedGoal = this.isGoalAddedAtMidyear(this.dropForm.goal);
      try {
        if (isAddedGoal) {
          // Find the backing adjustment — could be "add" (standalone added goal)
          // or "replace" (this goal is the new side of a replace pair).
          const existingAdj =
            this.adjustments.find(
              (a) => a.supersededById === this.dropForm.goal.id,
            ) || null;
          await this.removeAddedGoal(
            this.dropForm.goal.id,
            existingAdj ? existingAdj.id : null,
          );
        } else {
          this.fhir = {
            type: "goal-adjustment",
            adjustmentType: "drop",
            oldGoalId: this.dropForm.goal.id,
            reason: this.dropForm.reason.trim(),
            performancePlanId: this.performancePlan.id,
            goalType: this.dropForm.goalType,
          };
          await this.processFHIR();
        }
        this.dropDialog = false;
        this.showSnackbar(
          isAddedGoal ? "Added goal removed" : "Proposed drop saved",
          "success",
        );
        await this.refreshAll();
      } catch (e) {
        console.error(e);
        this.showSnackbar("Error saving drop proposal", "error");
      } finally {
        this.saving = false;
      }
    },

    openAddDialog(goalType, parent) {
      this.addForm = {
        goalType,
        parent,
        parentName: parent ? parent.name : "",
        name: "",
        description: "",
        reason: "",
        parentActivityId: null,
      };
      // Pre-load supervisor activities when opening for an objective
      if (
        goalType === "objective" &&
        !this.isPermanentSecretary &&
        this.supervisorActivities.length === 0
      ) {
        this.loadSupervisorActivities();
      }
      this.addDialog = true;
      this.$nextTick(
        () => this.$refs.addFormRef && this.$refs.addFormRef.resetValidation(),
      );
    },
    async confirmAdd() {
      console.log(this.addForm.parent);
      if (!this.$refs.addFormRef.validate()) return;
      this.saving = true;
      try {
        this.fhir = {
          type: "goal-adjustment",
          adjustmentType: "add",
          reason: this.addForm.reason.trim(),
          performancePlanId: this.performancePlan.id,
          newGoal: {
            goalType: this.addForm.goalType,
            name: this.addForm.name.trim(),
            description: this.addForm.description.trim(),
            performancePlanId:
              this.addForm.goalType === "objective"
                ? this.performancePlan.id
                : null,
            // Supervisor target link — populated for objectives
            parent:
              this.addForm.goalType === "objective"
                ? this.addForm.parentActivityId
                : this.addForm.parent.id,
            lifecycleStatus: "added-at-midyear",
          },
        };
        await this.processFHIR();
        this.addDialog = false;
        this.showSnackbar("Proposed addition saved", "success");
        await this.refreshAll();
      } catch (e) {
        console.error(e);
        this.showSnackbar("Error saving addition proposal", "error");
      } finally {
        this.saving = false;
      }
    },

    openModifyDialog(goal, goalType) {
      let existingAdj = null;
      if (this.isGoalAddedAtMidyear(goal)) {
        // Could be a standalone added goal (add adj) or the new side of a
        // replace pair (replace adj). Check both.
        existingAdj =
          this.adjustments.find(
            (a) => a.adjustmentType === "add" && a.supersededById === goal.id,
          ) ||
          this.adjustments.find(
            (a) =>
              a.adjustmentType === "replace" && a.supersededById === goal.id,
          ) ||
          null;
      }
      this.modifyForm = {
        goal,
        goalType,
        oldName: goal.name,
        oldDesc: goal.description,
        name: goal.name,
        description: goal.description,
        reason: existingAdj ? existingAdj.reason || "" : "",
        adjustmentId: existingAdj ? existingAdj.id || null : null,
        existingAdj,
      };
      this.modifyDialog = true;
      this.$nextTick(
        () =>
          this.$refs.modifyFormRef &&
          this.$refs.modifyFormRef.resetValidation(),
      );
    },
    async confirmModify() {
      if (!this.$refs.modifyFormRef.validate()) return;
      this.saving = true;
      const isAddedGoal = this.isGoalAddedAtMidyear(this.modifyForm.goal);
      const existingAdj = this.modifyForm.existingAdj;
      // If the goal being edited is the NEW side of a replace pair, we must
      // keep adjustmentType as "replace" and preserve the original oldGoalId
      // so that replaceAdjForGoal() continues to find it after the PUT.
      const isReplacementNewGoal =
        isAddedGoal && existingAdj && existingAdj.adjustmentType === "replace";
      try {
        this.fhir = {
          type: "goal-adjustment",
          adjustmentType: isReplacementNewGoal
            ? "replace"
            : isAddedGoal
            ? "add"
            : "replace",
          adjustmentId: existingAdj ? existingAdj.id : undefined,
          oldGoalId: isReplacementNewGoal
            ? existingAdj.oldGoalId
            : isAddedGoal
            ? null
            : this.modifyForm.goal.id,
          reason: this.modifyForm.reason.trim(),
          performancePlanId: this.performancePlan.id,
          goalType: this.modifyForm.goalType,
          newGoal: {
            id: isAddedGoal ? this.modifyForm.goal.id : undefined,
            goalType: this.modifyForm.goalType,
            name: this.modifyForm.name.trim(),
            description: this.modifyForm.description.trim(),
            parent: this.modifyForm.goal.parentId,
            performancePlanId:
              this.modifyForm.goalType === "objective"
                ? this.performancePlan.id
                : null,
            lifecycleStatus: "added-at-midyear",
          },
        };
        await this.processFHIR();
        this.modifyDialog = false;
        this.showSnackbar(
          isAddedGoal ? "Goal updated" : "Proposed replacement saved",
          "success",
        );
        await this.refreshAll();
      } catch (e) {
        console.error(e);
        this.showSnackbar("Error saving replacement proposal", "error");
      } finally {
        this.saving = false;
      }
    },

    confirmUndoAdjustment(adj) {
      this.undoTarget = adj;
      this.undoDialog = true;
    },
    async confirmUndo() {
      if (!this.undoTarget) return;
      this.saving = true;
      try {
        await this.removeAddedGoal(
          this.undoTarget.supersededById || null,
          this.undoTarget.id,
        );
        this.undoDialog = false;
        this.undoTarget = null;
        this.showSnackbar("Adjustment removed", "success");
        await this.refreshAll();
      } catch (e) {
        console.error(e);
        this.showSnackbar("Error removing adjustment", "error");
      } finally {
        this.saving = false;
      }
    },

    // Shared helper: delete an added-at-midyear goal (and its children) plus
    // the corresponding adjustment record, using the same direct DELETE bundle
    // approach as the performance planner.
    async removeAddedGoal(goalId, adjustmentId) {
      const bundle = {
        resourceType: "Bundle",
        type: "transaction",
        entry: [],
      };

      if (adjustmentId) {
        bundle.entry.push({
          resource: { resourceType: "Basic", id: adjustmentId },
          request: { method: "DELETE", url: "Basic/" + adjustmentId },
        });
      }

      if (goalId) {
        const params = new URLSearchParams({
          _id: goalId,
          "_revinclude:iterate": "Basic:parent",
          practitioner: this.queries.practitioner,
        });
        const res = await fetch("/fhir/Basic?" + params.toString());
        const data = await res.json();
        const entries = data.entry || [];

        const ofProfile = (profile) =>
          entries.filter((e) => e.resource.meta.profile.includes(profile));

        // Delete in reverse-dependency order: targets → KPIs → subs → activities → objectives
        for (const r of [
          ...ofProfile(
            "http://ihris.org/fhir/StructureDefinition/performance-target-profile",
          ),
          ...ofProfile(
            "http://ihris.org/fhir/StructureDefinition/performance-kpi-profile",
          ),
          ...ofProfile(
            "http://ihris.org/fhir/StructureDefinition/performance-subactivity-profile",
          ),
          ...ofProfile(
            "http://ihris.org/fhir/StructureDefinition/performance-activity-profile",
          ),
          ...ofProfile(
            "http://ihris.org/fhir/StructureDefinition/performance-objective-profile",
          ),
        ]) {
          bundle.entry.push({
            resource: r.resource,
            request: { method: "DELETE", url: "Basic/" + r.resource.id },
          });
        }
      }

      if (bundle.entry.length === 0) return;

      await fetch("/site/performance/deletePlan", {
        method: "DELETE",
        headers: { "Content-Type": "application/fhir+json" },
        redirect: "manual",
        body: JSON.stringify(bundle),
      });
    },

    openSubmitDialog() {
      if (!this.canSubmit) {
        this.showSnackbar(
          `${this.adjustedPlanErrors.length} issue(s) must be resolved before submitting`,
          "warning",
        );
        return;
      }
      this.submitDialog = true;
    },
    async confirmSubmit() {
      if (!this.canSubmit) {
        this.showSnackbar(
          `${this.adjustedPlanErrors.length} issue(s) must be resolved before submitting`,
          "warning",
        );
        return;
      }
      this.submitting = true;
      try {
        this.fhir = {
          type: "submit-goal-adjustment",
          performancePlanId: this.performancePlan.id,
        };
        await this.processFHIR();
        this.submitDialog = false;
        this.showSnackbar(
          this.isRevision
            ? "Adjustment resubmitted"
            : "Adjustment submitted to supervisor",
          "success",
        );
        await this.refreshAll();
      } catch (e) {
        console.error(e);
        this.showSnackbar("Error submitting adjustment", "error");
      } finally {
        this.submitting = false;
      }
    },

    async refreshAll() {
      await this.loadPerformancePlan();
      if (this.performancePlan) {
        await this.loadObjectives();
        await this.loadActivities();
        await this.loadSubActivities();
        await this.loadKpis();
        await this.loadTargets();
        await this.loadAdjustments();
        await this.loadReviews();
      }
    },

    toggleReview(i) {
      this.$set(this.expandedReviews, i, !this.expandedReviews[i]);
    },

    formatDate(d) {
      if (!d) return "";
      try {
        return new Intl.DateTimeFormat("en-GB", {
          day: "2-digit",
          month: "short",
          year: "numeric",
          hour: "2-digit",
          minute: "2-digit",
        }).format(new Date(d));
      } catch (e) {
        return d;
      }
    },

    goHome() {
      window.location.href =
        "/custom/performance?path=/lesotho/components/performance";
    },

    showSnackbar(message, color) {
      this.snackbarMessage = message;
      this.snackbarColor = color;
      this.snackbarIcon =
        color === "success"
          ? "mdi-check-circle"
          : color === "error"
          ? "mdi-alert-circle"
          : "mdi-information";
      this.snackbar = true;
    },
  },
};
