  font-weight: 700;
  color: #9a3412;
  margin-bottom: 6px;
}
.pga-validation-obj__errors {
  margin: 0;
  padding-left: 18px;
  color: #7c2d12;
  font-size: 12px;
}
.pga-validation-obj__errors li + li {
  margin-top: 4px;
}

/* CTA */
.pga-cta {
  display: flex;
  align-items: center;
  gap: 14px;
  background: #eef2ff;
  border: 1.5px dashed #c7d2fe;
  border-radius: 14px;
  padding: 16px 20px;
  margin-bottom: 20px;
}
.pga-cta__text {
}
.pga-cta__title {
  font-size: 14px;
  font-weight: 700;
  color: #3730a3;
  margin-bottom: 2px;
}
.pga-cta__sub {
  font-size: 12px;
  color: #64748b;
  line-height: 1.55;
}

/* OBJECTIVES GRID */
.pga-objectives {
  display: flex;
  gap: 16px;
  align-items: flex-start;
}
.pga-objectives__col {
  flex: 1 1 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 16px;
}
@media (max-width: 960px) {
  .pga-objectives {
    flex-direction: column;
  }
  .pga-objectives__col {
    width: 100%;
  }
}

/* OBJECTIVE CARD */
.pga-obj-card {
  border-radius: 18px;
  overflow: hidden;
  border: 1.5px solid #e7e5e4;
  background: white;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.04);
  transition: box-shadow 0.2s, transform 0.2s;
}
.pga-obj-card:hover {
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.1);
  transform: translateY(-2px);
}
.pga-obj-card--dropped {
  opacity: 0.8;
  border-color: #fecaca;
}
.pga-obj-card--replace {
  border-color: #fde68a;
}
.pga-obj-card--added {
  border-color: #a7f3d0;
}

.pga-obj-card__header {
  padding: 20px 20px 16px;
  position: relative;
}
.pga-obj-card__header-top {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
  flex-wrap: wrap;
}
.pga-obj-card__num {
  font-family: "JetBrains Mono", monospace;
  font-size: 13px;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.4);
  flex-shrink: 0;
}
.pga-obj-card__badges {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 1;
  flex-wrap: wrap;
}
.pga-obj-card__header-actions {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-left: auto;
}
.pga-obj-action-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 7px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  background: rgba(255, 255, 255, 0.1);
  cursor: pointer;
  transition: background 0.15s;
}
.pga-obj-action-btn:hover {
  background: rgba(255, 255, 255, 0.2);
}
.pga-obj-action-btn--danger:hover {
  background: rgba(239, 68, 68, 0.25);
  border-color: rgba(239, 68, 68, 0.4);
}
.pga-obj-action-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.pga-obj-card__title {
  font-size: 18px;
  font-weight: 800;
  color: white;
  letter-spacing: -0.03em;
  line-height: 1.2;
  margin: 0 0 6px;
}
.pga-obj-card__desc {
  font-size: 13px;
  color: rgba(255, 255, 255, 0.6);
  line-height: 1.5;
  margin: 0 0 8px;
}
.pga-obj-card__linked-target {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  background: rgba(94, 234, 212, 0.12);
  border: 1px solid rgba(94, 234, 212, 0.25);
  border-radius: 8px;
  padding: 7px 10px;
  font-size: 11px;
  color: rgba(255, 255, 255, 0.7);
  margin-top: 6px;
}
.pga-obj-card__linked-target strong {
  color: #5eead4;
  font-weight: 600;
}
.pga-obj-card__pending-reason {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  margin-top: 8px;
  padding: 6px 10px;
  border-radius: 8px;
  font-size: 11.5px;
  background: rgba(0, 0, 0, 0.2);
}
.pga-obj-card__pending-reason--drop {
  border-left: 3px solid rgba(239, 68, 68, 0.6);
}
.pga-obj-card__pending-reason--replace {
  border-left: 3px solid rgba(245, 158, 11, 0.6);
}
.pga-obj-card__pending-reason--add {
  border-left: 3px solid rgba(16, 185, 129, 0.6);
}
.pga-obj-card__pending-label {
  font-weight: 700;
  color: rgba(255, 255, 255, 0.8);
}
.pga-obj-card__pending-text {
  color: rgba(255, 255, 255, 0.65);
  font-weight: 500;
}
.pga-obj-card__body {
  padding: 16px;
}
.pga-obj-card__empty {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  color: #a8a29e;
  padding: 8px 0;
}
.pga-obj-card__empty a {
  color: #f97316;
  cursor: pointer;
  font-weight: 600;
}
.pga-obj-card__add-row {
  display: flex;
  gap: 5px;
  margin-top: 8px;
}
.pga-obj-card__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 20px;
  background: #fafaf8;
  border-top: 1px solid #f5f5f4;
  font-size: 12px;
  color: #a8a29e;
  font-weight: 600;
}

/* ACTIVITIES */
.pga-activities-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.pga-activity {
  background: #fafaf8;
  border: 1.5px solid #e7e5e4;
  border-radius: 12px;
  overflow: hidden;
}
.pga-activity--dropped {
  background: #fff5f5;
  border-color: #fecaca;
  opacity: 0.85;
}
.pga-activity--replace {
  background: #fffdf6;
  border-color: #fde68a;
}
.pga-activity--added {
  background: #f4fdf9;
  border-color: #a7f3d0;
}
.pga-activity__row {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px 12px;
  background: white;
}
.pga-activity__index {
  font-family: "JetBrains Mono", monospace;
  font-size: 10px;
  font-weight: 700;
  color: #6366f1;
  background: #eef2ff;
  padding: 3px 6px;
  border-radius: 5px;
  flex-shrink: 0;
  margin-top: 2px;
}
.pga-activity__info {
  flex: 1;
  min-width: 0;
}
.pga-activity__name {
  font-size: 13px;
  font-weight: 700;
  color: #1c1917;
  letter-spacing: -0.01em;
}
.pga-activity__desc {
  font-size: 11px;
  color: #a8a29e;
  margin-top: 2px;
  line-height: 1.4;
}
.pga-activity__badges {
  display: flex;
  gap: 5px;
  flex-wrap: wrap;
  margin-top: 4px;
}
.pga-activity__add-row {
  display: flex;
  gap: 5px;
  flex-shrink: 0;
  align-items: center;
  flex-wrap: wrap;
}

/* SUB-ACTIVITIES */
.pga-subs {
  border-top: 1px dashed #fed7aa;
  padding: 8px 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  background: #fffaf7;
}
.pga-sub {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  flex-wrap: wrap;
}
.pga-sub--dropped {
  opacity: 0.75;
}
.pga-sub--replace {
  background: rgba(254, 243, 199, 0.4);
  border-radius: 6px;
}
.pga-sub--added {
  background: rgba(209, 250, 229, 0.4);
  border-radius: 6px;
}
.pga-sub__line {
  width: 16px;
  height: 1px;
  background: #f59e0b;
  flex-shrink: 0;
  margin-top: 10px;
}
.pga-sub__index {
  font-family: "JetBrains Mono", monospace;
  font-size: 10px;
  color: #d97706;
  background: #fef3c7;
  padding: 2px 5px;
  border-radius: 4px;
  flex-shrink: 0;
  margin-top: 4px;
}
.pga-sub__info {
  flex: 1;
  min-width: 0;
}
.pga-sub__name {
  font-size: 12px;
  font-weight: 600;
  color: #78350f;
}
.pga-sub__badges {
  display: flex;
  gap: 5px;
  flex-wrap: wrap;
  margin-top: 3px;
}
.pga-sub__actions {
  display: flex;
  gap: 4px;
  flex-shrink: 0;
  margin-top: 2px;
  flex-wrap: wrap;
}

/* KPI ROWS */
.pga-kpis-group {
  border-top: 1px dashed #c7d2fe;
  padding: 8px 12px;
  background: #f5f3ff;
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.pga-kpis-group--act {
  background: #eef2ff;
}
.pga-kpi-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  padding: 6px 10px;
  background: white;
  border: 1.5px solid #ddd6fe;
  border-radius: 9px;
}
.pga-kpi-row--dropped {
  background: #fff5f5;
  border-color: #fecaca;
  opacity: 0.8;
}
.pga-kpi-row--cascade {
  background: #fff5f5;
  border-color: #fed7d7;
  opacity: 0.7;
}
.pga-kpi-row--added {
  background: #f4fdf9;
  border-color: #a7f3d0;
}
.pga-kpi-row__info {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 1;
  min-width: 0;
  flex-wrap: wrap;
}
.pga-kpi-row__name {
  font-size: 12px;
  font-weight: 600;
  color: #3730a3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.pga-kpi-row__target {
  display: flex;
  align-items: center;
  gap: 5px;
}
.pga-kpi-row__actions {
  display: flex;
  gap: 4px;
  flex-shrink: 0;
}
.pga-kpi-row__pending {
  width: 100%;
  padding: 4px 8px;
  border-radius: 6px;
  font-size: 10.5px;
  display: flex;
  gap: 5px;
  align-items: center;
  flex-wrap: wrap;
}

/* KPI TARGET CHIPS */
.pga-kpi-target-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 500;
  border: 1.5px solid #a7f3d0;
  background: #ecfdf5;
  color: #065f46;
}
.pga-kpi-target-chip--sub {
  border-color: #fed7aa;
  background: #fffbeb;
  color: #78350f;
}
.pga-target-chip__edit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  border-radius: 4px;
  border: none;
  background: transparent;
  cursor: pointer;
  padding: 0;
  opacity: 0;
  transition: opacity 0.15s, background 0.15s;
}
.pga-kpi-target-chip:hover .pga-target-chip__edit,
.pga-kpi-target-chip--sub:hover .pga-target-chip__edit {
  opacity: 1;
}
.pga-target-chip__edit:hover {
  background: rgba(0, 0, 0, 0.08);
}

/* LC CHIPS */
.pga-lc-chip {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 2px 7px;
  border-radius: 20px;
}
.pga-lc-chip--sm {
  font-size: 8.5px;
  padding: 2px 6px;
}
.pga-lc-chip--original-dropped {
  background: #fee2e2;
  color: #b91c1c;
}
.pga-lc-chip--added-at-midyear {
  background: #d1fae5;
  color: #065f46;
}

/* ADJ BADGES */
.pga-adj-badge {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  padding: 2px 7px;
  border-radius: 20px;
  letter-spacing: 0.03em;
}
.pga-adj-badge--sm {
  font-size: 8.5px;
  padding: 2px 6px;
}
.pga-adj-badge--drop {
  background: #fee2e2;
  color: #b91c1c;
  border: 1px solid #fecaca;
}
.pga-adj-badge--replace {
  background: #fffbeb;
  color: #92400e;
  border: 1px solid #fde68a;
}
.pga-adj-badge--add {
  background: #ecfdf5;
  color: #065f46;
  border: 1px solid #a7f3d0;
}

/* PENDING INLINE */
.pga-pending {
  display: flex;
  align-items: flex-start;
  gap: 5px;
  flex-wrap: wrap;
  padding: 4px 8px;
  border-radius: 6px;
  font-size: 11px;
}
.pga-pending--sm {
  font-size: 10.5px;
}
.pga-pending--drop {
  background: #fff5f5;
  border-left: 2px solid #fca5a5;
}
.pga-pending--replace {
  background: #fffbeb;
  border-left: 2px solid #fde68a;
}
.pga-pending--add {
  background: #f0fdf4;
  border-left: 2px solid #a7f3d0;
}
.pga-pending__label {
  font-weight: 700;
  color: #374151;
  flex-shrink: 0;
}
.pga-pending__reason {
  color: #64748b;
}

/* ADD INLINE BUTTONS */
.pga-add-inline {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
  border-radius: 20px;
  border: 1.5px dashed #c7d2fe;
  background: transparent;
  color: #6366f1;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  font-family: "Sora", sans-serif;
  transition: all 0.15s;
}
.pga-add-inline:hover {
  background: #eef2ff;
  border-color: #a5b4fc;
}
.pga-add-inline--block {
  display: flex;
  width: 100%;
  justify-content: center;
  margin-top: 10px;
  border-radius: 10px;
  padding: 8px;
}

/* ADD OBJECTIVE BUTTON */
.pga-add-objective {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  padding: 14px;
  margin-top: 16px;
  background: white;
  border: 2px dashed #c7d2fe;
  border-radius: 14px;
  color: #6366f1;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  font-family: "Sora", sans-serif;
  transition: all 0.15s;
}
.pga-add-objective:hover {
  background: #eef2ff;
  border-color: #a5b4fc;
}

/* MICRO BUTTONS */
.pga-micro-btn {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 3px 8px;
  border-radius: 20px;
  font-size: 10px;
  font-weight: 700;
  cursor: pointer;
  border: 1.5px solid;
  font-family: "Sora", sans-serif;
  transition: all 0.15s;
  white-space: nowrap;
}
.pga-micro-btn--sm {
  padding: 2px 6px;
  font-size: 9.5px;
}
.pga-micro-btn--amber {
  color: #d97706;
  border-color: #fde68a;
  background: #fffbeb;
}
.pga-micro-btn--amber:hover {
  background: #fef3c7;
}
.pga-micro-btn--red {
  color: #ef4444;
  border-color: #fecaca;
  background: #fff5f5;
}
.pga-micro-btn--red:hover {
  background: #fee2e2;
}
.pga-micro-btn--indigo {
  color: #6366f1;
  border-color: #c7d2fe;
  background: #eef2ff;
}
.pga-micro-btn--indigo:hover {
  background: #e0e7ff;
}
.pga-micro-btn--violet {
  color: #7c3aed;
  border-color: #ddd6fe;
  background: #f5f3ff;
}
.pga-micro-btn--violet:hover {
  background: #ede9fe;
}
.pga-micro-btn--emerald {
  color: #059669;
  border-color: #a7f3d0;
  background: #ecfdf5;
}
.pga-micro-btn--emerald:hover {
  background: #d1fae5;
}

/* BUTTONS */
.pga-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 9px 18px;
  border-radius: 10px;
  font-size: 13px;
  font-weight: 700;
  font-family: "Sora", sans-serif;
  cursor: pointer;
  border: none;
  transition: all 0.15s;
  letter-spacing: -0.01em;
  white-space: nowrap;
}
.pga-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.pga-btn--sm {
  padding: 7px 14px;
  font-size: 12px;
  border-radius: 8px;
}
.pga-btn--primary {
  background: #f97316;
  color: white;
}
.pga-btn--primary:hover:not(:disabled) {
  background: #ea580c;
  box-shadow: 0 4px 16px rgba(249, 115, 22, 0.4);
}
.pga-btn--outline {
  background: white;
  color: #292524;
  border: 1.5px solid #e7e5e4;
}
.pga-btn--outline:hover:not(:disabled) {
  border-color: #d6d3d1;
  background: #fafaf8;
}
.pga-btn--ghost {
  background: transparent;
  color: #78716c;
  border: 1.5px solid #e7e5e4;
}
.pga-btn--ghost:hover {
  background: #fafaf8;
}
.pga-btn--danger {
  background: #ef4444;
  color: white;
}
.pga-btn--danger:hover:not(:disabled) {
  background: #dc2626;
  box-shadow: 0 4px 16px rgba(239, 68, 68, 0.4);
}
.pga-btn--success {
  background: #059669;
  color: white;
}
.pga-btn--success:hover:not(:disabled) {
  background: #047857;
  box-shadow: 0 4px 16px rgba(5, 150, 105, 0.4);
}
.pga-btn--warning {
  background: #f59e0b;
  color: white;
}
.pga-btn--warning:hover:not(:disabled) {
  background: #d97706;
  box-shadow: 0 4px 16px rgba(245, 158, 11, 0.4);
}

/* DIALOGS */
.pga-dialog {
  border-radius: 20px !important;
  overflow: hidden;
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.18) !important;
}
.pga-dialog__strip {
  height: 4px;
}
.pga-dialog__strip--orange {
  background: linear-gradient(90deg, #f97316, #ea580c);
}
.pga-dialog__strip--red {
  background: linear-gradient(90deg, #ef4444, #dc2626);
}
.pga-dialog__strip--emerald {
  background: linear-gradient(90deg, #059669, #0d9488);
}
.pga-dialog__strip--amber {
  background: linear-gradient(90deg, #f59e0b, #d97706);
}
.pga-dialog__strip--neutral {
  background: linear-gradient(90deg, #64748b, #475569);
}
.pga-dialog__inner {
  background: white;
}
.pga-dialog__head {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 22px 24px 18px;
  border-bottom: 1px solid #f5f5f4;
  position: relative;
}
.pga-dialog__head-icon {
  width: 42px;
  height: 42px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.pga-dialog__head-icon--orange {
  background: linear-gradient(135deg, #f97316, #ea580c);
}
.pga-dialog__head-icon--red {
  background: linear-gradient(135deg, #ef4444, #dc2626);
}
.pga-dialog__head-icon--emerald {
  background: linear-gradient(135deg, #059669, #0d9488);
}
.pga-dialog__head-icon--amber {
  background: linear-gradient(135deg, #f59e0b, #d97706);
}
.pga-dialog__head-icon--neutral {
  background: linear-gradient(135deg, #64748b, #475569);
}
.pga-dialog__title {
  font-size: 17px;
  font-weight: 800;
  color: #1c1917;
  letter-spacing: -0.03em;
}
.pga-dialog__sub {
  font-size: 12px;
  color: #a8a29e;
  margin-top: 1px;
}
.pga-dialog__sub strong {
  font-weight: 700;
  color: #78716c;
}
.pga-dialog__x {
  position: absolute;
  right: 20px;
  top: 50%;
  transform: translateY(-50%);
  width: 30px;
  height: 30px;
  border-radius: 8px;
  border: 1.5px solid #e7e5e4;
  background: white;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s;
}
.pga-dialog__x:hover {
  background: #f5f5f4;
}
.pga-dialog__body {
  padding: 22px 24px;
}
.pga-dialog__foot {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding: 16px 24px;
  border-top: 1px solid #f5f5f4;
  background: #fafaf8;
}

/* FORM FIELDS */
.pga-field {
  margin-bottom: 18px;
}
